package co.kr.badara.dolswevoice;
import android.app.*;import android.os.*;import java.io.*;import java.nio.*;import java.util.*;import org.json.*;
/** Synthetic voice characterization only, never contacts HA. */
public final class ConnectedVoiceProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private float[] wav(String name)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContext().getAssets().open(name)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}ByteBuffer b=ByteBuffer.wrap(out.toByteArray()).order(ByteOrder.LITTLE_ENDIAN);b.position(12);while(b.remaining()>=8){byte[] tag=new byte[4];b.get(tag);int n=b.getInt();if(new String(tag,"US-ASCII").equals("data")){float[] x=new float[n/2];for(int i=0;i<x.length;i++)x[i]=b.getShort()/32768f;return x;}b.position(b.position()+n+(n%2));}throw new IOException("PCM data missing");}
 public void onStart(){Bundle report=new Bundle();SpeechEngine engine=null;try{engine=new SpeechEngine(getTargetContext().getAssets());JSONArray results=new JSONArray();for(String file:new String[]{"fire.wav","light.wav"}){String text=engine.recognize(wav(file));if(text.isEmpty())throw new AssertionError("No transcript");CommandRouter.Wake wake=CommandRouter.wake(text,"돌쇠야, 이모님");JSONObject item=new JSONObject().put("file",file).put("transcript",text).put("wake",wake.matched);try{if(!wake.matched)throw new IllegalArgumentException("No wake");CommandRouter.Plan plan=CommandRouter.plan(wake.remaining,Arrays.asList(new CommandRouter.Target("light.living","거실 불")));item.put("target",plan.target.id).put("service",plan.service).put("matched",plan.target.id.equals("light.living")&&plan.service.equals("turn_on"));}catch(Exception e){item.put("matched",false).put("detail",e.getMessage());}results.put(item);}report.putString("stream","CONNECTED_VOICE_PROBE_OK "+results);finish(Activity.RESULT_OK,report);}catch(Throwable e){report.putString("stream","CONNECTED_VOICE_PROBE_FAIL "+e);finish(Activity.RESULT_CANCELED,report);}finally{if(engine!=null)engine.close();}}
}
